WITH h AS (SELECT * FROM customer_care_level_history WHERE entfernt_am IS NULL), q AS (SELECT c.id, c.billing_type, c.pflegegrad AS pg_stamm, (SELECT h.pflegegrad FROM h WHERE h.customer_id = c.id AND h.valid_from <= CURRENT_DATE AND (h.valid_to IS NULL OR h.valid_to >= CURRENT_DATE) ORDER BY h.valid_from DESC LIMIT 1) AS pg_historie FROM customers c WHERE c.deleted_at IS NULL) SELECT befund, customer_id, detail FROM ( SELECT 'A Selbstzahler mit Pflegegrad (Stammdaten)' AS befund, id AS customer_id, 'customers.pflegegrad = ' || pg_stamm AS detail FROM q WHERE billing_type = 'selbstzahler' AND pg_stamm IS NOT NULL UNION ALL SELECT 'B Selbstzahler mit Pflegegrad (Historie)', h.customer_id, 'Eintrag ' || h.id || ': PG ' || h.pflegegrad || ', ' || h.valid_from || ' bis ' || coalesce(h.valid_to::text, 'offen') FROM h JOIN customers c ON c.id = h.customer_id WHERE c.deleted_at IS NULL AND c.billing_type = 'selbstzahler' UNION ALL SELECT 'C Stammdaten und Historie weichen ab (heute)', id, 'Stammdaten ' || coalesce(pg_stamm::text, 'kein PG') || ', Historie ' || coalesce(pg_historie::text, 'kein PG') FROM q WHERE pg_stamm IS DISTINCT FROM pg_historie UNION ALL SELECT 'D mehrere laufende Eintraege', customer_id, count(*) || ' offene Eintraege' FROM h WHERE valid_to IS NULL GROUP BY customer_id HAVING count(*) > 1 UNION ALL SELECT 'E umgedrehter Zeitraum', customer_id, 'Eintrag ' || id || ': ' || valid_from || ' bis ' || valid_to FROM h WHERE valid_to < valid_from UNION ALL SELECT 'F Kassen-Termin ohne nachgewiesenen Pflegegrad (Datenfehler)', a.customer_id, 'Termin ' || a.id || ' am ' || a.date FROM appointments a JOIN customers c ON c.id = a.customer_id WHERE a.deleted_at IS NULL AND c.deleted_at IS NULL AND c.billing_type <> 'selbstzahler' AND a.status = 'completed' AND a.date >= date_trunc('month', CURRENT_DATE - interval '1 month') AND NOT EXISTS (SELECT 1 FROM h WHERE h.customer_id = a.customer_id AND h.valid_from <= a.date AND (h.valid_to IS NULL OR h.valid_to >= a.date)) UNION ALL SELECT 'G Entwurf vor der Umstellung (verwerfen und neu erzeugen)', i.customer_id, i.invoice_number FROM invoices i WHERE i.status = 'entwurf' AND i.invoice_type IS DISTINCT FROM 'stornorechnung' AND EXISTS (SELECT 1 FROM invoice_line_items l WHERE l.invoice_id = i.id AND l.vat_rate_bp IS NULL) UNION ALL SELECT 'H Entwurf passt nicht zur Historie (verwerfen und neu erzeugen)', i.customer_id, i.invoice_number || ': Position am ' || l.appointment_date || ' PG ' || coalesce(l.pflegegrad_am_leistungstag::text, 'kein') || ', Historie ' || coalesce((SELECT h.pflegegrad FROM h WHERE h.customer_id = i.customer_id AND h.valid_from <= l.appointment_date AND (h.valid_to IS NULL OR h.valid_to >= l.appointment_date) ORDER BY h.valid_from DESC LIMIT 1)::text, 'kein') FROM invoices i JOIN invoice_line_items l ON l.invoice_id = i.id WHERE i.status = 'entwurf' AND i.invoice_type IS DISTINCT FROM 'stornorechnung' AND l.vat_rate_bp IS NOT NULL AND l.pflegegrad_am_leistungstag IS DISTINCT FROM (SELECT h.pflegegrad FROM h WHERE h.customer_id = i.customer_id AND h.valid_from <= l.appointment_date AND (h.valid_to IS NULL OR h.valid_to >= l.appointment_date) ORDER BY h.valid_from DESC LIMIT 1) ) befunde ORDER BY befund, customer_id;
